export async function cancel(id: string) {
  await db.tx(async t => {
    const { class_id } = await t.one('DELETE FROM bookings WHERE id=$1 RETURNING class_id', [id])
    const next = await t.oneOrNone('DELETE FROM waitlist WHERE ctid = (SELECT ctid FROM waitlist WHERE class_id=$1 ORDER BY joined_at LIMIT 1 FOR UPDATE SKIP LOCKED) RETURNING user_id', [class_id])
    if (next) await t.none('INSERT INTO bookings (class_id, user_id) VALUES ($1,$2)', [class_id, next.user_id])
  })
}
